insert into public.game_worlds (game, name, question_hook, class_plan)
select e->>0, e->>1, e->>2, e->3 from jsonb_array_elements($j$[["kayak_rush","Kayak Rush 3D","Câu hỏi hiện trên cổng phao phía trước; trả lời đúng trước khi tới cổng thì kayak bật Nitro lướt qua, sai thì kayak chậm lại và lắc nhẹ, không lật.",{"sizes":{"1-5":"Mỗi em một kayak đua cùng 2-3 kayak máy (độ khó theo bậc của lớp).","6-20":"Đội 2-4 kayak cùng màu. Mỗi màn hình hiện kayak của mình + 4 đối thủ gần nhất; bảng xếp hạng cả lớp ở góc.","21-50":"10 đội × 5 kayak, đua theo 2 lượt xuất phát (25 kayak/lượt) trên cùng đường sông; điểm đội = tổng thứ hạng. Mỗi máy chỉ vẽ 8 kayak gần nhất để nhẹ."},"roles":["Đội trưởng (chọn đường tắt)","Tay chèo Nitro","Hoa tiêu (đọc biển báo)","Người cứu hộ (giúp kayak lật)"],"scoring":"Thứ hạng + số Nitro + đường tắt mở được. Đúng 3 câu liền = Siêu Nitro.","avatars":"Mỗi học sinh ngồi kayak bằng nhân vật riêng ghép từ hồ sơ diện mạo, áo phao màu đội, mũ ngộ nghĩnh tự chọn.","style":"Nâng cấp theo gói thế giới sông bán thực (như 3 game mới); chướng ngại: khúc gỗ xoay, đá ngầm, xoáy nước, ghềnh, cây trôi."}],["multiverse_portal","Multiverse Portal RPG","Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.",{"sizes":{"1-5":"Mỗi em một Scarlet riêng đánh Boss của mình (bài tập về nhà), hoặc cả nhóm chung một Boss.","6-20":"Tổ đội 4-5 người chung một Boss (Co-op Raid), Boss có máu theo số người.","21-50":"10 tổ đội × 5 người, mỗi tổ đội một Boss riêng chạy song song; bảng xếp hạng tổ đội chung. Cuối trận, 10 tổ đội hợp sức đánh \"Boss Hợp Thể\" 2 phút."},"roles":["Kiếm sĩ (gây sát thương)","Pháp sư Khiên (đỡ đòn)","Thầy Thuốc (hồi máu)","Trinh sát Cổng (tìm điểm yếu)"],"scoring":"Sát thương + chí mạng + chuỗi đúng. Máy chủ chấm đáp án và máu Boss.","avatars":"Học sinh điều khiển phiên bản Scarlet của riêng mình (màu áo choàng và vũ khí lấy từ hồ sơ diện mạo).","style":"Giữ phong cách giả tưởng cách điệu (không dùng gói sông)."}],["summer_camp","Summer Camp Quests","Chạm vào vật thể đang phát sáng để mở câu hỏi nhỏ ngay cạnh nó; đúng thì hành động xảy ra trong thế giới, sai thì thử lại sau 5 giây, không trừ điểm nặng.",{"sizes":{"1-5":"Một Đội Lều chung; mỗi em làm lần lượt các trạm, máy chủ giao thêm việc cho người làm nhanh.","6-20":"2-4 Đội Lều (4-5 em/đội), mỗi đội một lều riêng và một lá cờ màu. Các đội cùng lấp đầy Bảng Nhiệm vụ trại chung.","21-50":"8-10 Đội Lều (5 em/đội). Trại chia 2 bãi cạnh nhau để không quá đông; mỗi trạm (bếp, lều, nước, củi) nhận tối đa 2 đội cùng lúc, xoay vòng mỗi 5 phút."},"roles":["Đội trưởng Lều (giữ Bảng Nhiệm vụ)","Thợ dựng lều","Người giữ lửa","Đầu bếp","Thủ kho (công cụ mở khóa)"],"scoring":"Mỗi hành động xong = 1-3 sao theo độ chính xác và tốc độ. Bảng Nhiệm vụ trại chung là thanh \"Boss\" của trận: cả lớp cùng lấp đầy. Đội Lều nhiều sao nhất được cắm cờ trên đỉnh trại.","avatars":"12 nhân vật dưới đây là người hướng dẫn và bạn trại trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo và đeo khăn màu Đội Lều.","safety":"Lửa, dao, rìu chỉ dùng qua hoạt ảnh có người lớn hướng dẫn; nhân vật luôn đeo găng khi nướng."}],["river_fishing","River Fishing Challenge","Cá cắn câu thì thanh căng dây hiện ra; các đáp án là những vùng màu trên thanh, kéo cần về đúng vùng đáp án để thu dây. Đúng: kéo cá lên, hiện cân nặng và chiều dài. Sai: dây chùng, cá thoát, mồi vẫn còn.",{"sizes":{"1-5":"Một thuyền nhôm chung (2-4 người) hoặc mỗi em một thuyền nhỏ cạnh bến; bảng kỷ lục cá nhân.","6-20":"Thuyền 3-4 người, mỗi em một cần riêng. 2-5 thuyền neo ở 2 khúc sông; bảng kỷ lục theo thuyền và cá nhân.","21-50":"Thuyền 4 người (50 em = 13 thuyền) rải trên 3 khúc sông: bến gỗ, giữa hồ, chân thác. Mỗi khúc sông tối đa 5 thuyền để không chật màn hình; ai cũng thấy bảng kỷ lục chung."},"roles":["Thuyền trưởng (chọn chỗ neo)","Thợ câu","Người giữ vợt","Người ghi kỷ lục"],"rules":{"score":"Điểm một con cá = cân nặng (kg) × 100 × hệ số độ hiếm (Thường 1, Khá 1,5, Hiếm 2,5, Cực hiếm 5). Trả lời nhanh cộng tới 20% điểm.","upgrade":"Mỗi 3 câu đúng: nâng một cấp cần (gỗ → sợi thủy tinh → carbon → vàng) hoặc chọn mồi mới. Cần cấp cao kéo nhanh hơn và giữ được cá to.","rarity":"Câu khó hơn (bậc cao hơn trong 5 bậc của gia sư) có tỉ lệ ra cá hiếm cao hơn. Cá Cực hiếm chỉ cắn khi đã có cần vàng.","release":"Cá được thả lại sông sau khi cân và chụp ảnh (thông điệp bảo vệ thiên nhiên)."},"avatars":"Mỗi học sinh đứng trên thuyền bằng nhân vật riêng ghép từ hồ sơ diện mạo, mặc áo phao màu thuyền. 12 nhân vật dưới đây là người dẫn chuyện và bạn câu trong phim.","safety":"Mọi nhân vật luôn mặc áo phao trên thuyền."}],["river_survival","River Survival: Escape & Pursuit","Bảng Nhiệm vụ góc trái: mỗi câu đúng hiện một chữ cái của mật mã nhiệm vụ; đủ chữ thì nhiệm vụ xong (1-3 sao).",{"sizes":{"1-5":"Tất cả học sinh vào Đội Chạy Trốn; Đội Săn Tìm là 2-3 người máy chạy chậm do máy chủ điều khiển, độ khó theo mức của lớp.","6-20":"Chia 60/40 (ví dụ 12 Chạy Trốn, 8 Săn Tìm). Nhóm 3-4 người cùng màu dây đeo, mỗi nhóm một Đội trưởng.","21-50":"Chia 60/40 (50 em = 30 Chạy Trốn, 20 Săn Tìm). Tiểu đội 5 người; bản đồ mở rộng 3 khu, mỗi khu một Chuồng Gỗ để không dồn 50 người một chỗ."},"roles":{"escapers":["Đội trưởng (giữ bản đồ, chọn đường)","Trinh sát (dò bụi cây an toàn)","Thợ giải mã (mật thư)","Người tìm nước","Người xóa dấu"],"pursuers":["Đội trưởng Săn Tìm (chia khu)","Người dò dấu chân","Người canh ống nhòm","Người chạy nhanh","Người giữ Chuồng Gỗ"]},"avatars":"12 nhân vật dưới đây là người dẫn chuyện và vai mẫu trong đoạn phim. Mỗi học sinh có nhân vật riêng ghép từ hồ sơ diện mạo (không trùng trong lớp) và mặc vest màu đội.","rules":{"teams":"Đội Chạy Trốn (vest xanh) và Đội Săn Tìm (vest cam). Tỉ lệ 60/40, làm tròn, ít nhất 1 người mỗi đội.","match":"Một trận liền mạch 30 phút, không chia hiệp. 2 chặng phụ chỉ mở khi gia sư bấm \"Kéo dài\".","win":"Hết giờ: nếu số Chạy Trốn còn tự do > số bị bắt thì Đội Chạy Trốn thắng; nếu Đội Săn Tìm bắt được hơn 50% thì Đội Săn Tìm thắng; hòa (đúng 50%) thì đội có tổng sao cao hơn thắng.","stars":"Mỗi nhiệm vụ cho 1-3 sao theo độ chính xác và tốc độ. Điểm = sao × 100 + điểm hành động (bắt, giải cứu, cướp lưới).","mvp":"MVP đội thắng (điểm cao nhất) nhận thêm 20% tổng điểm của toàn đội thua. Người điểm cao nhất đội thua nhận danh hiệu \"Gương Mặt Quật Cường\".","capture":"Đội Săn Tìm chạm Lưới Gắn Thẻ vào người Chạy Trốn = bắt. Người bị bắt về Chuồng Gỗ, không bị loại: tiếp tục giải mật thư hỗ trợ đội và có thể được giải cứu.","snatch":"Người Chạy Trốn lẻn sát sau lưng người Săn Tìm (2 m, không bị nhìn thấy) sẽ hiện nút \"Cướp lưới\": một câu hỏi 8 giây. Đúng: cướp được Lưới, người Săn Tìm mất lưới 45 giây. Sai: vị trí người Chạy Trốn hiện trên bản đồ đội Săn Tìm 5 giây.","net_power":"Lưới cướp được dùng 3 lần hoặc 60 giây: chạm người Săn Tìm làm họ đứng yên 10 giây (đuổi ngược), hoặc mở Chuồng Gỗ giải cứu 2 đồng đội. Hết lượt, lưới tự về trại Săn Tìm. Người Săn Tìm lấy lại lưới bằng cách chạm người đang cầm.","pursuer_skills":"Đội Săn Tìm cũng học: mỗi câu đúng nạp một kỹ năng: Quét dấu chân (hiện dấu trong bán kính 15 m, 8 giây), Ống nhòm (soi một bụi cây), Chạy nhanh (5 giây).","escaper_skills":"Đội Chạy Trốn: câu đúng nạp Xóa dấu (xóa dấu chân 10 giây), Ẩn nấp sâu (không bị Ống nhòm thấy 15 giây), Mồi nhử (tạo dấu chân giả).","dodge":"Khi bị chạm lưới, người Chạy Trốn có một câu \"Né lưới\" 6 giây, mỗi chặng dùng được 1 lần. Đúng thì thoát.","safety":"Không có cảnh đau, máu hay vũ khí thật. \"Bị bắt\" = bị gắn thẻ, nhân vật giơ tay cười. Dây thừng chỉ quấn cổng chuồng và ba lô, không trói người.","no_idle":"Không ai phải ngồi chờ: người bị bắt giải mật thư, người Săn Tìm trả lời để nạp kỹ năng."}}],["dino_journey","Hành trình khủng long","Chạm vào vật thể đang phát sáng trên đồng cỏ (dấu chân, vũng nước, bụi cỏ, quả trứng...) để mở câu hỏi nhỏ ngay cạnh nó; đúng thì khủng long con làm được việc đó (ngửi, vồ, uống, trốn, gầm), sai thì cha nhắc lại sau 5 giây, không trừ điểm nặng.",{"sizes":{"1-5":"Chơi một mình: em đóng chính chú khủng long con Mốc (tự đặt tên, chọn loài và màu); cha Gruk và cả bầy do máy điều khiển. Có 2-5 bạn thì mỗi bạn là một khủng long con trong bầy của em.","6-20":"Mỗi em là một khủng long con trong bầy: chọn loài và màu. Bầy chia 3-4 nhóm (4-5 em/nhóm), mỗi nhóm đi sau một khủng long lớn do máy dẫn đường; nhóm trả lời đúng nhiều thì cả bầy đi nhanh hơn và chọn được lối tắt.","21-50":"Bầy lớn: 8-10 nhóm 5 em cùng đi trên một đường mòn nhưng chia 2 bãi cỏ cạnh nhau để không đông; thanh \"Dũng cảm cả bầy\" dùng chung. Mỗi máy chỉ vẽ 8 khủng long gần nhất và tên bạn trong nhóm để máy yếu vẫn mượt."},"roles":["Khủng long con đi đầu (đọc dấu chân)","Người canh gió (báo nguy hiểm)","Người tìm nước","Người giữ trứng và tổ","Chim đưa tin của bầy (báo tin cho cả nhóm)"],"scoring":"Mỗi việc đúng = 1-3 sao theo độ chính xác và tốc độ. Thanh \"Dũng cảm cả bầy\" là thanh Boss chung: cả lớp cùng lấp đầy; nhóm nhiều sao nhất được cha khen và đi đầu đàn ở chặng sau.","avatars":"Chế độ một mình: nhân vật là chú khủng long con Mốc. Chế độ lớp: mỗi học sinh một khủng long con, chọn loài (T-rex, Raptor, Triceratops, Stegosaurus, Diplodocus, Sauropod) và màu; trùng loài được, khác màu. 12 nhân vật dưới đây là cha, người lớn, bạn nhỏ và muông thú trong câu chuyện.","species":{"trex":"dino_trex_brown","raptor":"dino_raptor_rider","triceratops":"dino_triceratops","stegosaurus":"dino_stegosaurus","diplodocus":"dino_diplodocus","sauropod":"dino_sauropod_grey"},"safety":"Không máu, không cảnh đau. Cảnh bắt nạt chỉ là xô đẩy, gầm gừ và chặn đường; ai \"ngã\" chỉ ngồi xuống, đứng dậy được. Săn mồi dùng hoạt ảnh vồ mồi rồi cắt cảnh; thú nhỏ luôn chạy thoát hoặc \"ngủ\" một lát, không bị làm hại.","subtitle_rule":"Mức Beginner: toàn tiếng Việt. Mức A1 đến B2: từ có bậc thấp hơn mức đang chọn hiện tiếng Anh, từ còn lại tiếng Việt. Mức C1: toàn tiếng Anh."}]]$j$::jsonb) e
on conflict (game) do update set name = excluded.name, question_hook = excluded.question_hook, class_plan = excluded.class_plan, updated_at = now();
